from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # The color sequence is written along the last non-background row.
    key_row = None
    for r in range(h - 1, -1, -1):
        if sum(v != bg for v in grid[r]) >= 2:
            key_row = r
            break
    if key_row is None:
        return out
    sequence = [v for v in grid[key_row] if v != bg]

    # Find the separate 2x2 colored objects.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x),
                               (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            r0, r1 = min(ys), max(ys)
            c0, c1 = min(xs), max(xs)
            if len(cells) == 4 and r1 - r0 == 1 and c1 - c0 == 1:
                objects.append({
                    "color": color, "r0": r0, "r1": r1,
                    "c0": c0, "c1": c1
                })

    if len(objects) != len(sequence) or not objects:
        return out

    row_coords = sorted({obj["r0"] for obj in objects})
    col_coords = sorted({obj["c0"] for obj in objects})
    for obj in objects:
        obj["ri"] = row_coords.index(obj["r0"])
        obj["ci"] = col_coords.index(obj["c0"])

    def adjacent(a, b):
        return abs(a["ri"] - b["ri"]) + abs(a["ci"] - b["ci"]) == 1

    def search(path, used):
        if len(path) == len(sequence):
            return path[:]
        target = sequence[len(path)]
        previous = objects[path[-1]]
        for i, obj in enumerate(objects):
            if i not in used and obj["color"] == target and adjacent(previous, obj):
                used.add(i)
                path.append(i)
                result = search(path, used)
                if result is not None:
                    return result
                path.pop()
                used.remove(i)
        return None

    order = None
    for i, obj in enumerate(objects):
        if obj["color"] == sequence[0]:
            order = search([i], {i})
            if order is not None:
                break
    if order is None:
        return out

    # Connect each object to the next one, using the departing object's color.
    for i, j in zip(order, order[1:]):
        a, b = objects[i], objects[j]
        color = a["color"]

        if a["ri"] == b["ri"]:
            left, right = (a, b) if a["c0"] < b["c0"] else (b, a)
            y0 = max(a["r0"], b["r0"])
            y1 = min(a["r1"], b["r1"])
            for y in range(y0, y1 + 1):
                for x in range(left["c1"] + 1, right["c0"]):
                    if out[y][x] == bg:
                        out[y][x] = color
        else:
            top, bottom = (a, b) if a["r0"] < b["r0"] else (b, a)
            x0 = max(a["c0"], b["c0"])
            x1 = min(a["c1"], b["c1"])
            for x in range(x0, x1 + 1):
                for y in range(top["r1"] + 1, bottom["r0"]):
                    if out[y][x] == bg:
                        out[y][x] = color

    return out
